    report(spin_system,'Nottingham DNP relaxation theory terms have been incorporated.');

end

% Add scalar relaxation of the first kind
if ismember('SRFK',spin_system.rlx.theories)

    % Inform the user
    report(spin_system,'scalar relaxation of the first kind...');

    % Set local assumptions
    spin_system_local=assume(spin_system,'labframe');

    % Get the background Hamiltonian
    H0=hamiltonian(spin_system_local);

    % Set local assumptions
    spin_system_local=assume(spin_system,'labframe','couplings');

    % Replace couplings with their modulation depths
    [rows,cols]=find(~cellfun(@isempty,spin_system.rlx.srfk_mdepth));
    spin_system_local.inter.coupling.matrix=cell(size(spin_system.inter.coupling.matrix));
    for n=1:numel(rows)
        spin_system_local.inter.coupling.matrix{rows(n),cols(n)}=...
             2*pi*eye(3)*spin_system.rlx.srfk_mdepth{rows(n),cols(n)};
    end

    % Get the modulated coupling Hamiltonian
    H1=hamiltonian(spin_system_local);

    % Erase the modifications
    clear('spin_system_local');

    % Eliminate numerical noise
    H0=(H0+H0')/2; H1=(H1+H1')/2;

    % Call the scalar relaxation superoperator
    report(spin_system,'integrating the SRFK component...');
    RS=rlx_scalar(spin_system,H0,H1,spin_system.rlx.srfk_tau_c);

    % Catch abuse of Redfield theory
    max_rate=max(abs(diag(RS)));
    for n=1:numel(spin_system.rlx.srfk_tau_c)
        if (1/max_rate)<spin_system.rlx.srfk_tau_c{n}(2)
            report(spin_system,['1/max(diag(R)) = ' num2str(1/max_rate) ...
                                ', srfk_tau_c = ' num2str(spin_system.rlx.srfk_tau_c{n}(2))]);
            error('T1,2>>srfk_tau_c validity condition violation in Redfield theory');
        end
    end

    % Add to total and tidy up 
    R=R+RS; clear('H0','H1','RS');

    % Inform the user
    report(spin_system,'SRFK terms have been incorporated.');

end

% Add scalar relaxation of the second kind
if ismember('SRSK',spin_system.rlx.theories)

    % Inform the user
    report(spin_system,'scalar relaxation of the second kind...');

    % Preallocate the answers
    R1=zeros(spin_system.comp.nspins,1); R2=zeros(spin_system.comp.nspins,1);

    % Loop over sources
    for k=spin_system.rlx.srsk_sources

        % Relaxation rates of the source spin
        Lz_k=state(spin_system,{'Lz'},{k}); Lz_k=Lz_k/norm(Lz_k,2);
        Lp_k=state(spin_system,{'L+'},{k}); Lp_k=Lp_k/norm(Lp_k,2);
        T1k=-1/real(Lz_k'*R*Lz_k); T2k=-1/real(Lp_k'*R*Lp_k);

        % Source spin quantum number
        Sk=(spin_system.comp.mults(k)-1)/2;

        % Inform the user
        report(spin_system, ['SRSK from spin ' num2str(k) ' (' spin_system.comp.isotopes{k} ...
                             ', T1=' num2str(T1k) ' s, T2=' num2str(T2k) ' s):']);

        % Loop over potential destinations
        for n=setdiff(1:spin_system.comp.nspins,...
                      spin_system.rlx.srsk_sources)

            % Only process heteronuclear pairs
            if ~strcmp(spin_system.comp.isotopes{n},spin_system.comp.isotopes{k})

                % Determine the coupling (rad/s)
                A=trace(spin_system.inter.coupling.matrix{n,k})/3+...
                  trace(spin_system.inter.coupling.matrix{k,n})/3;

                % Catch out-of-scope situations
                if ((2*pi/T1k)<10*abs(A))||((2*pi/T2k)<10*abs(A))
                    error('SRSK theory is not applicable: source spin relaxation is too slow');
                end

                % Find frequency difference
                delta_omega=spin_system.inter.basefrqs(n)-...
                            spin_system.inter.basefrqs(k);

                % Compute Abragam's expressions
                R1add=(2/3)*(A^2)*Sk*(Sk+1)*(T2k/(1+delta_omega^2*T2k^2));
                R2add=(1/3)*(A^2)*Sk*(Sk+1)*(T1k+T2k/(1+delta_omega^2*T2k^2));
                R1(n)=R1(n)+R1add; R2(n)=R2(n)+R2add;

                % Inform the user of significant terms
                if (R1add>spin_system.tols.liouv_zero)||...
                   (R2add>spin_system.tols.liouv_zero)
                    report(spin_system, ['  > onto spin ' num2str(n) ...
                                         ' (' spin_system.comp.isotopes{n}...
                                         '): +' num2str(R1add) ...
                                         ' Hz to R1, +' num2str(R2add) ' Hz to R2']);
                end

            end

        end 
    end

    % Clone the spin system structure
    spin_system_local=spin_system;
    spin_system_local.rlx.theories={'t1_t2'};
    spin_system_local.rlx.r1_rates=num2cell(R1');
    spin_system_local.rlx.r2_rates=num2cell(R2');

    % Issue a recursive call for SRSK
    report(spin_system,'recursive call for SRSK relaxation terms...'); 
    R=R+relaxation(spin_system_local);

    % Inform the user
    report(spin_system,'SRSK relaxation theory terms have been incorporated.');

end

% Print matrix density statistics
report(spin_system,['full relaxation superoperator density ' num2str(100*nnz(R)/numel(R))...
                    '%, nnz ' num2str(nnz(R)) ', sparsity ' num2str(issparse(R))]);

% Decide the fate of dynamic frequency shifts
switch spin_system.rlx.dfs

    case 'keep'

        % Do nothing and inform the user
        report(spin_system,'dynamic frequency shifts have been kept.');

    case 'ignore'

        % Kill the dynamic frequency shifts
        R=real(R);

        % Inform the user
        report(spin_system,'dynamic frequency shifts have been ignored.');

    otherwise

        % Complain and bomb out
        error('invalid value of the inter.rlx_dfs parameter.');

end

% Decide the fate of the off-diagonal components
switch spin_system.rlx.keep

    case 'diagonal'

        % Pull out the diagonal
        R=diag(diag(R));

        % Inform the user
        report(spin_system,'all cross-relaxation terms have been ignored.');

    case 'kite'

        % Refuse to process inappropriate cases
        if ~strcmp(spin_system.bas.formalism,'sphten-liouv')
            error('kite option is only available for sphten-liouv formalism.');
        end

        % Compile the index of all longitudinal spin orders
        [~,M]=lin2lm(spin_system.bas.basis);
        long_states=find(sum(abs(M),2)==0);
% Propagation step function. Uses Taylor propagation and sparse exponenti-
% ation where appropriate. Supports piecewise-constant, piecewise-linear,
% and piecewise quadratic product quadratures. Syntax:
%
%                   rho=step(spin_system,L,rho,time_step)
%
% Arguments:
%
%      L          -  Liouvillian or Hamiltonian to be used for 
%                    propagation; centre point piecewise-constant
%                    rule if one matrix is supplied, piecewise-
%                    linear rule if two matrices {left, right} 
%                    are supplied, piecewise-quadratic if three
%                    matrices {left, midpoint, right} are given.
%
%      rho        -  state vector or density matrix to be propagated
%
%      time_step  -  length of the time step to take
%
% Note: we initially had a faithful implementation of the Krylov process
%       here - subspace, orthogonalisation, projection, etc., but in all
%       our testing it was much inferior to the reordered Taylor process
%       that is currently implemented below.
%
% Note: the peculiar sequence of algebraic operations in the code below
%       is designed to minimize the memory footprint in large cases.
%
% i.kuprov@soton.ac.uk
% ledwards@cbs.mpg.de
% a.acharya@soton.ac.uk
%
% <https://spindynamics.org/wiki/index.php?title=step.m>

function rho=step(spin_system,L,rho,time_step)

% Check consistency
grumble(L,rho,time_step);

% Do we want to run on GPU?
want_gpu=ismember('gpu',spin_system.sys.enable);

% Is the generator already on GPU?
if isnumeric(L)
    if want_gpu&&(~isa(L,'gpuArray'))
        L=gpuArray(L); 
    end
else
    for n=1:numel(L)
        if want_gpu&&(~isa(L{n},'gpuArray'))
            L{n}=gpuArray(L{n});
        end
    end
end

% Is the state already on GPU?
if isnumeric(rho)
    if want_gpu&&(~isa(rho,'gpuArray'))
        rho=gpuArray(rho); 
    end
else
    for n=1:numel(rho)
        if want_gpu&&(~isa(rho{n},'gpuArray'))
            rho{n}=gpuArray(rho{n});
        end
    end
end

% Are we using a Liouville space formalism?
liouv_space=ismember(spin_system.bas.formalism,{'sphten-liouv','zeeman-liouv'});

% In Hilbert space, run the shortcut
if ~liouv_space

    % Get the propagator
    if isnumeric(L)

        % Centre point piecewise-constant propagator
        P=propagator(spin_system,L,time_step);

    elseif numel(L)==2

        % Left edge + right edge piecewise-linear propagator
        P=propagator(spin_system,isergen(L{1},[],L{2},time_step),time_step);

    elseif numel(L)==3

        % Left edge + midpoint + right edge piecewise-quadratic propagator
        P=propagator(spin_system,isergen(L{1},L{2},L{3},time_step),time_step);

    end

    % Perform the propagation step
    if iscell(rho)
        parfor n=1:numel(rho)
            rho{n}=P*rho{n}*P';
        end
    else
        rho=P*rho*P';
    end

    % Exit
    return;

end

% Make sure state is full
if issparse(rho), rho=full(rho); end

% Estimate scaling coefficient
scaling=max(abs(rho),[],'all');

% Catch zeros
if scaling==0 
    report(spin_system,'WARNING: all-zero state received');
    return;
end

% Scale the state
rho=rho/scaling;

% Subdivide the time step
if isnumeric(L)
    norm_mat=cheap_norm(L)*abs(time_step);
else
    norm_mat=max(cellfun(@cheap_norm,L))*abs(time_step);
end
nsteps=ceil(norm_mat/2);

% Step checks
if nsteps>1e4

    % Catch the common mistake of supplying wildly unreasonable |L*dt|
    error('either dt is too long, or L is too big: |L*dt|>1e4, check both.');

elseif nsteps>100

    % Warn user if too many substeps are needed
    report(spin_system,['WARNING: ' num2str(nsteps)...
                        ' substeps required, consider using evolution() here.']);
end

% Decide if parallelisation is sensible
parfor_makes_sense=(size(rho,1)>256)&&(size(rho,2)>32)&&...
                   (poolsize>0)&&(~want_gpu);

% Proceed with the propagation
if parfor_makes_sense

    % Parallel loop over rho stack
    parfor m=1:size(rho,2)

        % Call Taylor-times-vector procedure
        rho(:,m)=reordered_taylor(L,rho(:,m),time_step,nsteps);

    end

else

    % Call Taylor-times-vector procedure
    rho=reordered_taylor(L,rho,time_step,nsteps);

end

% Scale the state back
rho=scaling*rho;

end

% Taylor-times-vector procedure
function rho=reordered_taylor(L,rho,t,nsteps)

% Loop over substeps
for n=1:nsteps

    % Start the Taylor series
    next_term=rho; k=1; tol=eps('double');

    % Loop until convergence
    while nnz(abs(next_term)>tol)>0

        if isnumeric(L)

            % Centre point piecewise-constant propagator
            next_term=-(1i/k)*(t/nsteps)*(L*next_term);

        elseif numel(L)==2

            % Re-usable intermediates
            rho_a=L{1}*next_term; rho_b=L{2}*next_term;

            % Left edge + right edge piecewise-linear propagator
            next_term=-(1i/2)*(1/k)*(t/nsteps)*(rho_a+rho_b)+...
                       (1/6)*(1/k)*(t^2/nsteps)*(L{1}*rho_b-L{2}*rho_a);

        elseif numel(L)==3

            % Re-usable intermediates
            rho_a=L{1}*next_term; rho_b=L{2}*next_term; rho_c=L{3}*next_term;

            % Left edge + midpoint + right edge piecewise-quadratic propagator
            next_term=-(1i/6)*(1/k)*(t/nsteps)*(rho_a+4*rho_b+rho_c)+...
                       (1/12)*(1/k)*(t^2/nsteps)*(L{1}*rho_c-L{3}*rho_a);

        end

        % Add the next term and increment
        rho=rho+next_term; k=k+1;

    end

    % Display non-monotonic convergence warning
    if k>32, warning(['loss of accuracy in the Taylor series, k=' num2str(k) ...
                      ', use evolution() here instead of step()']); end

end

end

% Consistency enforcement
function grumble(L,rho,time_step)
if (~isnumeric(time_step))||(~isscalar(time_step))
    error('time_step must be a scalar.');
end
if (~isnumeric(L))&&(~iscell(L))
    error('L must be a matrix or a cell array of matrices');
end
if (~isnumeric(rho))&&(~iscell(rho))
    error('L must be a matrix, a vector, or a cell array thereof');
end
end

% Evans boldly put 50 atm of ethylene in a cell with 25 atm of oxygen. The
% apparatus subsequently blew up, but luckily not before he had obtained
% the spectra shown in Figure 8.
%
% A.J. Mehrer and R.S. Mulliken, Chem. Rev. 69 (1969) 639-656.

% Generates Hilbert space density matrices and Liouville space state 
% vectors from their human-readable descriptions. Syntax:
%
%              rho=state(spin_system,states,spins,method)
%
% This function supports three types of calls:
%
% 1. If states is a string and spins is a string
%
%                      states='Lz'; spins='13C';
%
% the function returns the sum of the corresponding single-spin densi-
% ty matrices (Hilbert space) or state vectors (Liouville space) on 
% all spins of that type. Valid labels for states in this type of call
% are 'E' (identity), 'Lz', 'Lx', 'Ly', 'L+', 'L-', 'Tl,m' (irreduci-
% ble spherical tensor, l and m are integers), 'CTx', 'CTy', 'CTz',
% 'CT+','CT-' (central transition operators in the Zeeman basis). Va-
% lid labels for spins are standard isotope names, as well as 'elect-
% rons', 'nuclei', and 'all'.
%
% 2. If states is a string and spins is a vector
%
%                      states='Lz'; spins=[1 2 4];
%
% the function returns the sum of all single-spin density matrices
% (Hilbert space) or state vectors (Liouville space) for all spins
% with the specified numbers. Valid labels for states are the same as
% in Item 1 above.
%
% 3. If states is a cell array of strings and spins is a cell array
%    of numbers:
%
%                      states={'Lz','L+'}; spins={1,2};
%
% then a product state density matrix (Hilbert space) or state vector
% (Liouville space) is produced. In the case above, Spinach will gene-
% rate LzS+ density matrix in Hilbert space or its state vector in Li-
% ouville space. Valid labels for operators are the same as in Item 1
% above.
%
% Method argument has the following effect in sphten-liouv formalism:
%
%    'cheap'  - the state vector is generated without
%               normalisation. For very large spin sys-
%               tems this is much faster
%
%    'exact'  - exact state vector with correct normalisation,
%               this is the default when the last argument is
%               skipped in the function call
%
%    'chem'   - the exact state vector weighted with the 
%               concentrations specified in inter.chem.concs
%               field under chemical kinetics parameters
%
% This option is ignored in zeeman-hilb and zeeman-liouv formalisms
% because there are no cheap shortcuts and kinetics is not available.
%
% Outputs:
%
%     rho     - a Hilbert space density matrix or a Liouville
%               space state vector
% 
% d.sayostyanov@soton.ac.uk
% luke.edwards@ucl.ac.uk
% i.kuprov@soton.ac.uk
%
% <https://spindynamics.org/wiki/index.php?title=state.m>

function rho=state(spin_system,states,spins,method)

% Validate the input
grumble(spin_system,states,spins);

% Default is to use consistent state norms
if ~exist('method','var'), method='exact'; end

% Get the unit state
switch spin_system.bas.formalism

    case 'sphten-liouv'

        % Unit population of T(0,0) state, normalisation is
        % such because prod(spin_system.comp.mults) can be-
        % come too large for double precision arithmetic
        unit=sparse(1,1,1,size(spin_system.bas.basis,1),1);

    case 'zeeman-liouv'

        % Stretched unit matrix, normalisation matched to 
        % the Hilbert space because systems are small
        unit=speye(prod(spin_system.comp.mults)); unit=unit(:);

end

% Decide how to proceed
switch spin_system.bas.formalism

    case 'sphten-liouv'

        % Choose the state vector generation methos
        switch method

            % Careless normalisation
            case 'cheap'

                % Parse the specification
                [opspecs,coeffs]=human2opspec(spin_system,states,spins);

                % Compute correlation orders
                correlation_orders=sum(logical(spin_system.bas.basis),2);

                % Locate each operator in the basis
                indices=zeros(size(coeffs));
                parfor n=1:numel(opspecs) %#ok<*PFBNS>

                    % Find states with the same correlation order
                    possibilities=(correlation_orders==nnz(opspecs{n}));

                    % Pin down the required state
                    for k=find(opspecs{n})
                        possibilities=and(possibilities,spin_system.bas.basis(:,k)==opspecs{n}(k)); 
                    end

                    % Double-check
                    if nnz(possibilities)>1
                        error('basis descriptor ambiguity detected.');
                    elseif nnz(possibilities)<1
                        error('the requested state is not present in the basis.');
                    end

                    % Locate the state 
                    indices(n)=find(possibilities);

                end

                % Assemble the state vector
                nrows=size(spin_system.bas.basis,1); ncols=1;
                rho=sparse(indices,ones(size(indices)),coeffs,nrows,ncols);

            % Careful normalisation
            case 'exact'

                % Apply a left side product superoperator to the unit state
                rho=operator(spin_system,states,spins,'left')*unit;

            % Chemical weighing
            case 'chem'

                % Parse the specification
                [opspecs,coeffs]=human2opspec(spin_system,states,spins);

                % Preallocate the state vector
                rho=spalloc(size(spin_system.bas.basis,1),1,0);

                % Get the basis dimension
                matrix_dim=size(spin_system.bas.basis,1);

                % Sum the states with concentrations
                for n=1:numel(opspecs)

                    % Identify active spins
                    active_spins=find(opspecs{n});

                    % Find out which chemical species they are in
                    species=true(1,numel(spin_system.chem.parts)); 
                    for k=1:numel(active_spins)
                        species=species&cellfun(@(x)ismember(active_spins(k),x),spin_system.chem.parts);
                    end

                    % Check state validity
                    if nnz(species)~=1
                        error('the spin state requested crosses chemical species boundaries.');
                    end

                    % Adjust the coefficient
                    coeffs(n)=coeffs(n)*spin_system.chem.concs(species);

                    % Get the operator
                    A=p_superop(spin_system,opspecs{n},'left');
                    A=sparse(A(:,1),A(:,2),A(:,3),matrix_dim,matrix_dim);

                    % Get the state vector
                    rho=rho+coeffs(n)*A*unit;

                end

            otherwise

                % Complain and bomb out
                error('unknown state generation method.');

        end

    case 'zeeman-liouv'

        % Apply a left side product superoperator to the unit state
        rho=operator(spin_system,states,spins,'left')*unit; 

    case 'zeeman-hilb'

        % Generate a Hilbert space operator
        rho=operator(spin_system,states,spins);

    otherwise

        % Complain and bomb out
        error('unknown formalism specification.');

end

end

% Input validation function
function grumble(spin_system,states,spins)
if ~isfield(spin_system,'bas')
    error('basis set information is missing, run basis() before calling this function.');
end
if (~(ischar(states)&&ischar(spins)))&&...
   (~(iscell(states)&&iscell(spins)))&&...
   (~(ischar(states)&&isnumeric(spins)))
    error('invalid state specification.');
end
if iscell(states)&&iscell(spins)&&(numel(states)~=numel(spins))
    error('spins and operators cell arrays should have the same number of elements.');
end
if iscell(states)&&any(~cellfun(@ischar,states))
    error('all elements of the operators cell array should be strings.');
end
if isnumeric(spins)
    if (~isreal(spins))||(~isrow(spins))||any(mod(spins,1)~=0)||any(spins<1)
        error('when numeric, spins must be a row of positive integers.');
    end
    if numel(spins)~=numel(unique(spins))
        error('spin list must not have any repetitions.');
    end
end
if iscell(spins)
    for n=1:numel(spins)
        if (~isreal(spins{n}))||(mod(spins{n},1)~=0)||(spins{n}<1)
            error('when a cell array, spins must contain positive integers.');
        end
    end
    spins=cell2mat(spins(:));
    if numel(spins)~=numel(unique(spins))
        error('spin list must not have any repetitions.');
    end
end
if isempty(spins), error('spin list cannot be empty.'); end
end

