% Internal consistency test for the state vectors and matrices
% in each of the three formalisms supported by Spinach.
%
% i.kuprov@soton.ac.uk

function normalization_1()

% System specification
sys.magnet=14.1;
sys.isotopes={'1H','235U'};
inter.zeeman.scalar={2.5 1.0};
inter.coupling.scalar{1,2}=10;
inter.coupling.scalar{2,1}=10;
spin_system=create(sys,inter);

% Preallocate the answer
norm_diffs=zeros(6,3,'like',1i);

% Compute norm differences
formalisms={'zeeman-hilb','zeeman-liouv','sphten-liouv'};
for n=1:numel(formalisms)
    bas.formalism=formalisms{n};
    bas.approximation='none';
    spin_system=basis(spin_system,bas);
    Ux=state(spin_system,'Lx','235U');
    Uy=state(spin_system,'Ly','235U');
    Uz=state(spin_system,'Lz','235U');
    Hx=state(spin_system,'Lx','1H');
    Hy=state(spin_system,'Ly','1H');
    Hz=state(spin_system,'Lz','1H');
    norm_diffs(1,n)=norm(full(Ux))-norm(full(Uy));
    norm_diffs(2,n)=norm(full(Uy))-norm(full(Uz));
    norm_diffs(3,n)=norm(full(Uz))-norm(full(Ux));
    norm_diffs(4,n)=norm(full(Hx))-norm(full(Hy));
    norm_diffs(5,n)=norm(full(Hy))-norm(full(Hz));
    norm_diffs(6,n)=norm(full(Hz))-norm(full(Hx));
end

% Display the answers
if any(abs(norm_diffs)>1e-6,'all')
    error('Internal norm consistency test FAILED.');
else
    disp('Internal norm consistency test PASSED.');
end

end

% Test of internal consistency for state and operator 
% generation across the three formalisms supported by
% Spinach. Two- and four-spin states are tested.
%
% i.kuprov@soton.ac.uk

function state_consistency()

% Magnet field
sys.magnet=14.1;

% Set the spin system
sys.isotopes={'1H','1H','1H','1H'};
inter.zeeman.scalar={0 0 0 0};

% Loop over the formalisms
Fs={'zeeman-hilb','zeeman-liouv','sphten-liouv'};
for n=1:numel(Fs)

    % Basis set
    bas.formalism=Fs{n};
    bas.approximation='none';

    % Hush the logs
    sys.output='hush';
    sys.disable={'hygiene'};

    % Spinach housekeeping
    spin_system=create(sys,inter);
    spin_system=basis(spin_system,bas);

    % Unit state
    U=state(spin_system,{'E','E','E','E'},{1 2 3 4});

    % Two-spin singlet-triplet state sum test
    combos={[1 2],[1 3],[1 4],[2 1],[2 3],[2 4],...
            [3 1],[3 2],[3 4],[4 1],[4 2],[4 3]};
    parfor k=1:numel(combos) %#ok<*PFBNS>
        S=singlet(spin_system,combos{k}(1),combos{k}(2));
        [TU,T0,TD]=triplet(spin_system,combos{k}(1),combos{k}(2));
        if norm(S+TU+T0+TD-U,1)>1e-6
            error([Fs{n} ': state construction test FAILED.']);
        end
    end

    % Four-spin singlet-triplet state sum test
    combos=num2cell(perms([1 2 3 4]),2);
    parfor k=1:numel(combos)
        S=four_spin_states(spin_system,num2cell(combos{k}),'S(x)S')+...
          four_spin_states(spin_system,num2cell(combos{k}),'S(x)TU')+...
          four_spin_states(spin_system,num2cell(combos{k}),'S(x)T0')+...
          four_spin_states(spin_system,num2cell(combos{k}),'S(x)TD')+...
          four_spin_states(spin_system,num2cell(combos{k}),'TU(x)S')+...
          four_spin_states(spin_system,num2cell(combos{k}),'T0(x)S')+...
          four_spin_states(spin_system,num2cell(combos{k}),'TD(x)S')+...
          four_spin_states(spin_system,num2cell(combos{k}),'TU(x)TU')+...
          four_spin_states(spin_system,num2cell(combos{k}),'T0(x)TU')+...
          four_spin_states(spin_system,num2cell(combos{k}),'TD(x)TU')+...
          four_spin_states(spin_system,num2cell(combos{k}),'TU(x)T0')+...
          four_spin_states(spin_system,num2cell(combos{k}),'T0(x)T0')+...
          four_spin_states(spin_system,num2cell(combos{k}),'TD(x)T0')+...
          four_spin_states(spin_system,num2cell(combos{k}),'TU(x)TD')+...
          four_spin_states(spin_system,num2cell(combos{k}),'T0(x)TD')+...
          four_spin_states(spin_system,num2cell(combos{k}),'TD(x)TD');
        if norm(S-U,1)>1e-6
            error([Fs{n} ': state construction test FAILED.']); 
        end
    end

    % Good news to the user
    disp([Fs{n} ': state construction test PASSED.']);

end

end

                % Assemble operator in XYZ form
                J=cell(nterms,1);
                for n=1:nterms

                    % Get the combined coefficient
                    coeff=descr.ist_coeff(n,r^2+k-1)*descr.irr_comp(n,r^2+m-1);

                    % Store the operator if significant
                    if abs(coeff)>spin_system.tols.liouv_zero
                        J{n}=[oper{n}(:,1) oper{n}(:,2) coeff*oper{n}(:,3)];
                        J{n}(abs(J{n}(:,3))<spin_system.tols.liouv_zero,:)=[];
                    end

                end
                J(cellfun(@isempty,J))=[]; J=cell2mat(J);

                % Convert XYZ form to sparse matrix
                if isempty(J)
                    Q{r}{k,m}=mprealloc(spin_system,0);
                else
                    J=sparse(J(:,1),J(:,2),J(:,3),dim,dim);
                    Q{r}{k,m}=clean_up(spin_system,J,spin_system.tols.liouv_zero);
                end

            end
        end

    end

end

% Clean up and do the reporting
clear('J','descr','irr_comp','iso_coeff','oper');
report(spin_system,['Hamiltonian assembly took ' num2str(toc()) ' seconds']);

% Process giant spin Hamiltonian terms
if build_aniso

    % Detect the maximum spherical rank
    max_rank=max(cellfun(@numel,spin_system.inter.giant.coeff));
    report(spin_system,['maximum spherical rank in the giant spin Hamiltonian: ' num2str(max_rank)]);

    % Expand the data structure
    for r=1:max_rank
        if numel(Q)<r
            Q{r}=cell(2*r+1,2*r+1);
            Q{r}(1:(2*r+1),1:(2*r+1))={mprealloc(spin_system,0)};
        end
    end

    % Build the Hamiltonian
    for n=1:spin_system.comp.nspins

        % Loop over spherical ranks
        for r=1:numel(spin_system.inter.giant.coeff{n})

            switch spin_system.inter.giant.strength{n}

                case 'strong'

                    % Inform the user
                    report(spin_system,['complete giant spin Hamiltonian of rank ' num2str(r) ' for spin ' num2str(n) '...']);

                    % Loop over spherical tensor indices
                    for k=1:(2*r+1)

                        % Build the tensor spec
                        ist_spec=['T' num2str(r) ',' num2str(r-k+1)];

                        % Inform the user
                        report(spin_system,['           ' ist_spec ' x ' ...
                               num2str(spin_system.inter.giant.coeff{n}{r}(k)/(2*pi),'%+0.5e') ' Hz']);

                        % Get the irreducible spherical tensor
                        T=operator(spin_system,{ist_spec},{n},operator_type);

                        % Loop over coefficient indices
                        for m=1:(2*r+1)

                            % Operator building
                            Q{r}{k,m}=Q{r}{k,m}+T*spin_system.inter.giant.coeff{n}{r}(m);

                        end

                    end

                case 'secular'

                    % Inform the user
                    report(spin_system,['secular giant spin Hamiltonian of rank ' num2str(r) ' for spin ' num2str(n) '...']);

                    % Build the tensor spec
                    ist_spec=['T' num2str(r) ',' num2str(0)];

                    % Inform the user
                    report(spin_system,['           ' ist_spec ' x ' ...
                           num2str(spin_system.inter.giant.coeff{n}{r}(r+1)/(2*pi),'%+0.5e') ' Hz']);

                    % Only use the zero projection for T_lm
                    T=operator(spin_system,{ist_spec},{n},operator_type);

                    % Loop over coefficient indices
                    for m=1:(2*r+1)

                        % Operator building
                        Q{r}{r+1,m}=Q{r}{r+1,m}+T*spin_system.inter.giant.coeff{n}{r}(m);

                    end

                case 'ignore'

                    % Tell the user
                    report(spin_system,['giant spin Hamiltonian terms of rank ' num2str(r)...
                                        ' for spin ' num2str(n) ' have been ignored.']); 

            end

        end

    end

end

% Remind the user about the anisotropic part
if ~build_aniso
    report(spin_system,'WARNING - only the isotropic part has been returned.');
end

% Warn about all-zero Hamiltonians
if (~build_aniso)&&(nnz(H)==0)
    report(spin_system,'WARNING - the Hamiltonian is ALL ZERO.');
end

% Print memory diagnostics
H_whos=whos('H'); report(spin_system,['memory footprint of H array: ' num2str(H_whos.bytes/1024^3) ' GB']);
if build_aniso
    Q_whos=whos('Q'); report(spin_system,['memory footprint of Q array: ' num2str(Q_whos.bytes/1024^3)  ' GB']);
end

end

% Consistency enforcement
function grumble(spin_system,operator_type)
if ~isfield(spin_system,'bas')
    error('basis set information is missing, run basis() before calling this function.');
end
if (~isfield(spin_system.inter.coupling,'strength'))||...
   (~isfield(spin_system.inter.zeeman,'strength'))     
    error('assumption information is missing, run assume() before calling this function.');
end
