function value=sum(values,varargin)
if (nargin>=2)&&ischar(varargin{end})&&strcmp(varargin{end},'all')
    varargin=varargin(1:end-1);
    value=builtin('sum',values(:),varargin{:});
else
    value=builtin('sum',values,varargin{:});
end
end
function result=all(values,varargin)
if (nargin==2)&&ischar(varargin{1})&&strcmp(varargin{1},'all')
    result=builtin('all',values(:));
else
    result=builtin('all',values,varargin{:});
end
end
